inline bool editQueueCompletion(CWnd* owner,Json& q){
 Form d("Queue completion actions",300,190,owner);d.dialogUnits=true;bool accepted=false;
 d.init=[&]{auto steps=queueCompletionSteps(q);auto controls=std::make_shared<std::vector<std::pair<std::string,CWnd*>>>();int y=9;
  for(const auto& name:std::vector<std::string>{"Open file","Disconnect dial-up / VPN","Sleep","Hibernate","Shut down","Restart","Exit UDM"}){controls->push_back({name,d.check(name,std::find(steps.begin(),steps.end(),name)!=steps.end(),10,y,280)});y+=18;}
  auto force=d.check("Force processes to terminate",yes(q,"FinishForce"),22,140,268);
  auto enable=[&d,controls,force]{bool can=false;for(auto& entry:*controls)if((entry.first=="Shut down"||entry.first=="Restart")&&d.checked(entry.second))can=true;force->EnableWindow(can);if(!can)force->SendMessage(BM_SETCHECK,BST_UNCHECKED);};
  for(auto& entry:*controls)d.bind(entry.second,enable);enable();
  d.accept=[&d,&q,&accepted,controls,force]{std::vector<std::string> selected;for(auto& entry:*controls)if(d.checked(entry.second))selected.push_back(entry.first);setQueueCompletionSteps(q,selected,d.checked(force));accepted=true;d.close();};
  d.defaultButton(d.button("OK",178,169,50,d.accept));d.button("Cancel",239,169,50,[&]{d.close(IDCANCEL);});
 };d.DoModal();return accepted;
}
